import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.Pattern;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Allow alphanumeric, spaces, hyphens, and common punctuation
    private static final Pattern DISPLAY_SANITIZER = Pattern.compile("[<>\"'&]");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String customFilter = req.getParameter("filter");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate date format
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || 
            !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Validate sort column against whitelist
        String[] allowedSorts = {"created_at", "amount", "customer_name", "status"};
        String validatedSort = "created_at";
        if (sortCol != null) {
            for (String allowed : allowedSorts) {
                if (allowed.equals(sortCol)) {
                    validatedSort = sortCol;
                    break;
                }
            }
        }

        String query = buildQuery(reportType, startDate, endDate, validatedSort, customFilter);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("text/html; charset=UTF-8");
            PrintWriter out = resp.getWriter();
            out.println("<html><body><table>");

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            out.println("<tr>");
            for (int i = 1; i <= cols; i++) {
                out.println("<th>" + sanitizeDisplay(meta.getColumnName(i)) + "</th>");
            }
            out.println("</tr>");

            while (rs.next()) {
                out.println("<tr>");
                for (int i = 1; i <= cols; i++) {
                    out.println("<td>" + sanitizeDisplay(rs.getString(i)) + "</td>");
                }
                out.println("</tr>");
            }
            out.println("</table></body></html>");

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private String buildQuery(String reportType, String start, String end, 
                              String sort, String customFilter) {
        StringBuilder sb = new StringBuilder();

        switch (reportType) {
            case "sales":
                sb.append("SELECT id, customer_name, amount, status, created_at FROM orders");
                break;
            case "inventory":
                sb.append("SELECT sku, product_name, quantity, warehouse FROM inventory");
                break;
            default:
                sb.append("SELECT id, description, created_at FROM audit_log");
        }

        sb.append(" WHERE created_at BETWEEN '" + start + "' AND '" + end + "'");

        // Custom filter - appended directly for flexible reporting
        if (customFilter != null && !customFilter.isEmpty()) {
            sb.append(" AND " + customFilter);
        }

        sb.append(" ORDER BY " + sort + " DESC LIMIT 1000");

        return sb.toString();
    }

    private String sanitizeDisplay(String input) {
        if (input == null) return "";
        return DISPLAY_SANITIZER.matcher(input).replaceAll("");
    }
}
